%%%% xls_parse
%%%%
%%%% TODO:
%%%%    + more 'object oriented' design than a direct transcription?

-module(xls_parse).
-export([]).
-compile(export_all).

-define(MAX_TAGS, 255).  % bounded by tag width in axis header

-define(debug(X), begin io:format("~w@~w: ~p~n", [?FUNCTION_NAME, ?LINE, X]), X end).

to_xls(Filename) ->
    {ok, Forms} = parse_file(Filename),
    PublicStructNames = find_attribute(Forms, xls_tags),

    ["// ", Filename, ".x\n",
    """
    // This file is auto-generated by xls_parse. Manual changes will be over-
    // written the next time it is generated. Better to modify the Erlang input.

    import axis;

    const NOREPLY = u1:0;  // some standard erlang tokens
    const REPLY = u1:1;
    const OK = u1:0;


    """,
    "const MAX_PAYLOAD = u32:3;\n\n",  % TODO: don't bake this in.
    "pub enum Tag : u8 {\n",
    "  NONE = u8:0,\n",
    [
        ["  ", string:uppercase(atom_to_list(Atom)), " = u8:", integer_to_list(Index), ",\n"]
        ||  {Index, Atom} <- lists:enumerate([state(Forms) | PublicStructNames])
    ],
    "}\n\n",
    [
        [struct_from_record(Record), "\n",
         structfrombits_from_record(Record), "\n",
         bitsfromstruct_from_record(Record), "\n"]
        ||  Op <- PublicStructNames,
            Record <- [find_record(Forms, Op)]
    ],
    struct_from_record(find_record(Forms, state(Forms))), "\n",
    dummy_bitsfromstruct(find_record(Forms, state(Forms))), "\n",
    """
    proc Service {
      req_in:   chan<axis::Frame> in;
      resp_out: chan<axis::Frame> out;

      config(req_in: chan<axis::Frame> in, resp_out: chan<axis::Frame> out) {
        (req_in, resp_out)
      }


    """,
    % TODO: actually look at the code here and do nontrivial init
    [
        "  init {\n",
        ["    let s = zero!<", string:titlecase(atom_to_list(state(Forms))), ">();\n"],
        ["    (Tag::", string:uppercase(atom_to_list(state(Forms))), ", s, bits_from_", atom_to_list(state(Forms)), "(s))\n"],
        "  }\n\n"
    ],
    """
      next(state: (Tag, State, bits[0])) {
        let (tok1, frame) = recv(join(), req_in);

        // cognate to {reply, Reply, State}
        let (resp, new_state) = match frame.header.op as Tag {

    """,
    [
        ["\nTag::", string:uppercase(Op), " => {\n",
        "let request = ", Op, "_from_bits(frame.payload);\n",
        Body,
        % TODO: Op below is wrong, should be Tag, but how to extract it??
        ["(axis::pack(", RetVal, ".1.0 as u8, ", RetVal, ".1.2), ", RetVal, ".2)\n"],
        "},\n"]
        ||  Clause <- handle_call(Forms),
            Op <- [atom_to_list(op_from_clause(Clause))],
            {Body, RetVal} <- [branch_from_clause(Clause, ["request", "state"])]
    ],
    [
        ["\nTag::", string:uppercase(Op), " => {\n",
        "let request = ", Op, "_from_bits(frame.payload);\n",
        Body,
        ["(zero!<axis::Frame>(), ", RetVal, ".1)\n"],
        "},\n"]
        ||  Clause <- handle_cast(Forms),
            Op <- [atom_to_list(op_from_clause(Clause))],
            {Body, RetVal} <- [branch_from_clause(Clause, ["request", "state"])]
    ],
    """

        _ => {
          // TODO: emit error code here
          (zero!<axis::Frame>(), state)
        }

        };

        let txid = frame.header.txid;
        let resp2 = axis::Frame { header: axis::Header { txid, ..resp.header }, ..resp };
        send_if(tok1, resp_out, resp2.header.op != (Tag::NONE as u8), resp2);
        new_state
      }
    }


    """,
    """
    proc Top {
      ext_recv: chan<axis::Beat> in;
      ext_send: chan<axis::Beat> out;

      config(ext_recv: chan<axis::Beat> in, ext_send: chan<axis::Beat> out) {
        let (req_p,  req_c ) = chan<axis::Frame, u32:1>("req");
        let (resp_p, resp_c) = chan<axis::Frame, u32:1>("resp");

        spawn axis::Rx(ext_recv, req_p);
        spawn Service(req_c, resp_p);
        spawn axis::Tx(resp_c, ext_send);

        (ext_recv, ext_send)
      }

      init { () }

      next(state: ()) { state }
    }

    """].

emitted_ops(Forms) ->
    % TODO: more robustly deal with union types, type redirection
    ExtractRecord = fun ({type, _1, record, [{atom, _2, Atom}]}) -> Atom end,
    {attribute, _1, spec, {
        {handle_call, 2},
        [{type, _2, 'fun', [_Source, {type, _3, tuple, [
            {atom, _4, reply},
            ReturnType,
            _State
        ]}]}]
    }} = find_spec(Forms, handle_call, 2),
    case ReturnType of
        {type, _5, union, Records} ->
            lists:map(ExtractRecord, Records);
        {type, _6, record, _Spec} ->
            [ExtractRecord(ReturnType)]
    end.

state(Forms) ->
    InitSpec = find_spec(Forms, init, 1),
    {attribute, _1, spec, {
        {init, 1},
        [{type, _2, 'fun', [
            _3,
            {type, _4, record, [{atom, _5, StateAtom}]}
        ]}]
    }} = InitSpec,
    StateAtom.

-spec op_from_clause(erl_parse:af_clause()) -> atom().
op_from_clause(Clause) ->
    {clause, _1, [{record, _2, Atom, _Contents} | _Rest], _3, _Body} = Clause,
    Atom.

-record(clause_state, {
    anonymous_counter = 0 :: integer(),
    named_counters = #{} :: #{atom() => integer()},
    statements = [] :: iolist(),
    reference = none :: none | string()
}).

anonymous_variable(State = #clause_state{anonymous_counter = Counter}) ->
    {State#clause_state{anonymous_counter = Counter + 1}, [$_ | integer_to_list(Counter)]}.

get_name(_State, Name) ->
    string:lowercase(atom_to_list(Name)) ++ "_1".

uniquify(State = #clause_state{named_counters = Counters}, NameAtom) ->
    Name = string:lowercase(atom_to_list(NameAtom)),
    Counter = maps:get(Name, Counters, 0) + 1,
    NamedCounters = Counters#{Name => Counter},
    NewName = Name ++ [$_ | integer_to_list(Counter)],
    {NewName, State#clause_state{named_counters = NamedCounters}}.

destructure_lhs({var, _L, NameAtom}, State) ->
    {Name, NewState} = uniquify(State, NameAtom),
    RHS = NewState#clause_state.reference,
    Bind = ["let ", Name, " = ", RHS, ";\n"],
    NewState#clause_state{statements = [Bind | NewState#clause_state.statements]};
destructure_lhs({record, _L, _Atom, Slots}, State) ->
    % TODO: convert RHS to type _Atom? need RHS to be a bag of bits in that case, or else to know RHS's type
    RecordRef = State#clause_state.reference,
    IntermediateState = lists:foldl(
        fun({record_field, _1, {atom, _2, SlotAtom}, LHS}, ThisState) ->
            Slot = atom_to_list(SlotAtom),
            Substate = ThisState#clause_state{reference = [RecordRef, ".", Slot]},
            destructure_lhs(LHS, Substate)
        end,
        State, Slots
    ),
    IntermediateState#clause_state{reference = RecordRef}.
%% TODO: tuple

op('+', [Left, Right]) -> [Left, " + ", Right];
op('band', [Left, Right]) -> [Left, " & ", Right];
op('bor', [Left, Right]) -> [Left, " | ", Right];
op('bnot', [Operand]) -> ["!", Operand].

statement_from_statement(String, State) when is_list(String) ->
    State#clause_state{reference = String};
statement_from_statement({atom, _L, Atom}, State) ->
    State#clause_state{reference = string:uppercase(atom_to_list(Atom))};
statement_from_statement({var, _L, Atom}, State) ->
    State#clause_state{reference = get_name(State, Atom)};
statement_from_statement({integer, _L, Int}, State) ->
    State#clause_state{reference = integer_to_list(Int)};
statement_from_statement(X, State) when is_tuple(X) andalso op == element(1, X) ->
    [op, _L, Op | Args] = tuple_to_list(X),
    {BwdArgRefs, IntermediateState} = lists:foldl(
        fun(Arg, {ArgRefs, ThisState}) ->
            NewState = statement_from_statement(Arg, ThisState#clause_state{reference = none}),
            {[NewState#clause_state.reference | ArgRefs], NewState}
        end,
        {[], State}, Args
    ),
    {FinalState, ResultName} = anonymous_variable(IntermediateState),
    FinalState#clause_state{
        reference = ResultName,
        statements = [
            ["let ", ResultName, " = ", op(Op, lists:reverse(BwdArgRefs)), ";\n"]
            | FinalState#clause_state.statements
        ]
    };
statement_from_statement({tuple, _L, Slots}, State) ->
    {BwdReferences, IntermediateState} = lists:foldl(
        fun(Slot, {References, ThisState}) ->
            NewState = statement_from_statement(Slot, ThisState#clause_state{reference = none}),
            {[NewState#clause_state.reference | References], NewState}
        end,
        {[], State}, Slots
    ),
    {FinalState, TupleName} = anonymous_variable(IntermediateState),
    FinalState#clause_state{
        reference = TupleName,
        statements = [
            ["let ", TupleName, " = (", [[Ref, ", "] || Ref <- lists:reverse(BwdReferences)], ");\n"]
            | FinalState#clause_state.statements
        ]
    };
statement_from_statement({record, _L, NameAtom, Fields}, State) ->
    {Assignments, IntermediateState} = lists:foldl(
        fun({record_field, _1, {atom, _2, FieldAtom}, RHS}, {Assignments, ThisState}) ->
            NewState = statement_from_statement(RHS, ThisState#clause_state{reference = none}),
            {Assignments#{FieldAtom => NewState#clause_state.reference}, NewState}
        end,
        {#{}, State}, Fields
    ),
    {SecondState, InternalName} = anonymous_variable(IntermediateState),
    {FinalState, StructName} = anonymous_variable(SecondState),
    FinalState#clause_state{
        reference = StructName,
        statements = [
            ["let ", StructName, " = (",  % tag, struct, bits
            "Tag::", string:uppercase(atom_to_list(NameAtom)), ", ",
            InternalName, ", ",
            "bits_from_", atom_to_list(NameAtom), "(", InternalName, ")"
            ");\n"],
            ["let ", InternalName, " = ", string:titlecase(atom_to_list(NameAtom)), " {\n",
                [["  ", atom_to_list(FieldAtom), ": ", Reference, ",\n"]
                    || FieldAtom := Reference <- Assignments],
            "  ..zero!<", string:titlecase(atom_to_list(NameAtom)), ">()\n",
            "};\n"]
            | FinalState#clause_state.statements
        ]
    };
statement_from_statement({record, _L, ToUpdate, NameAtom, UpdateFields}, State) ->
    InputState = statement_from_statement(ToUpdate, State),
    {Assignments, IntermediateState} = lists:foldl(
        fun({record_field, _1, {atom, _2, FieldAtom}, RHS}, {Assignments, ThisState}) ->
            NewState = statement_from_statement(RHS, ThisState#clause_state{reference = none}),
            {Assignments#{FieldAtom => NewState#clause_state.reference}, NewState}
        end,
        {#{}, InputState}, UpdateFields
    ),
    {SecondState, InternalName} = anonymous_variable(IntermediateState),
    {FinalState, StructName} = anonymous_variable(SecondState),
    FinalState#clause_state{
        reference = StructName,
        statements = [
            ["let ", StructName, " = (",  % tag, struct, bits
            "Tag::", string:uppercase(atom_to_list(NameAtom)), ", ",
            InternalName, ", ",
            "bits_from_", atom_to_list(NameAtom), "(", InternalName, ")"
            ");\n"],
            ["let ", InternalName, " = ", string:titlecase(atom_to_list(NameAtom)), " {\n",
                [["  ", atom_to_list(FieldAtom), ": ", Reference, ",\n"] || FieldAtom := Reference <- Assignments],
            "  ..(", InputState#clause_state.reference, ").1\n",
            "};\n"]
            | FinalState#clause_state.statements
        ]
    }
    % NameAtom { whatever: stuff, to: update, ..old }
    % emit a new anonymous tuple with tag and bits



    ;
statement_from_statement({call, _L, MF, Args}, State) ->
    {BwdArgRefs, IntermediateState} = lists:foldl(
        fun(Arg, {ArgRefs, ThisState}) ->
            NewState = statement_from_statement(Arg, ThisState#clause_state{reference = none}),
            {[NewState#clause_state.reference | ArgRefs], NewState}
        end,
        {[], State}, Args
    ),
    {FinalState, ResultName} = anonymous_variable(IntermediateState),
    {remote, _1, {atom, _2, Module}, {atom, _3, FAtom}} = MF,
    FinalState#clause_state{
        reference = ResultName,
        statements = [
            ["let ", ResultName, " = ", Module:transpile(FAtom, lists:reverse(BwdArgRefs)), ";\n"]
            | FinalState#clause_state.statements
        ]
    };
statement_from_statement({record_field, _L, Object, _RecordAtom, {atom, _LL, SlotAtom}}, State) ->
    IntermediateState = statement_from_statement(Object, State),
    {FinalState, ResultName} = anonymous_variable(IntermediateState),
    FinalState#clause_state{
        reference = ResultName,
        statements = [
            ["let ", ResultName, " = ", FinalState#clause_state.reference, ".1.", atom_to_list(SlotAtom), ";\n"]
            | FinalState#clause_state.statements
        ]
    };
statement_from_statement({match, _L, LHS, RHS}, State) ->
    RHSState = statement_from_statement(RHS, State),
    destructure_lhs(LHS, RHSState).

-spec branch_from_clause(erl_parse:af_clause(), [atom()]) -> {iolist(), string()}.
branch_from_clause(Clause, ArgVals) ->
    {clause, _1, ArgPatterns, _2, Body} = Clause,
    InjectMatch = fun
        F({{match, LineNo, LHS, RHS}, Arg}) ->
            {match, LineNo, LHS, F({RHS, Arg})};
        F({X, Arg}) ->
            {match, element(2, X), X, Arg}
    end,
    BigBody = case ArgPatterns of
        [{nil, _L}] -> Body;
        _ -> lists:map(InjectMatch, lists:zip(ArgPatterns, ArgVals)) ++ Body
    end,
    OutState = lists:foldl(
        fun(Statement, State) ->
            statement_from_statement(Statement, State#clause_state{reference = none})
        end,
        #clause_state{}, BigBody
    ),
    {lists:reverse(OutState#clause_state.statements), OutState#clause_state.reference}.
    % TODO: Finally, all the named vars are asserted equal, else `ERR_MATCH` is
    % emitted; else `{reply, Reply, NewState}` is emitted from the match.

parse_file(Filename) ->
    {ok, Epp} = epp:open([{name, Filename}]),
    try
        {ok, epp:parse_file(Epp)}
    after
        epp:close(Epp),
        err
    end.

-spec struct_from_record(erl_parse:af_record_decl()) -> iolist().
struct_from_record(RecordForm) ->
    {attribute, _L, record, {NameAtom, Fields}} = RecordForm,
    Name = lists:delete($_, atom_to_list(NameAtom)),
    StructName = string:titlecase(Name),
    ["struct ", StructName, " {\n",
        [io_lib:format("  ~w : ~s,~n", [element(3, element(3, Field)), case xls_types:from_erl(Type) of X when is_atom(X) -> atom_to_list(X); X -> X end])
            ||  {typed_record_field, Field, Type} <- Fields
        ],
    "}\n"].

-spec structfrombits_from_record(erl_parse:af_record_decl()) -> iolist().
structfrombits_from_record(RecordForm) ->
    {attribute, _L, record, {NameAtom, Fields}} = RecordForm,
    Name = lists:delete($_, atom_to_list(NameAtom)),
    StructName = string:titlecase(Name),
    ["fn ", string:lowercase(StructName), "_from_bits<N: u32>(raw: bits[N]) -> ", StructName, " {\n",
    "  ", StructName, " {\n",
    lists:reverse(element(1, lists:foldl(
        fun(
            {typed_record_field, {record_field, _1, {atom, _2, Slot}, _Default}, Type},
            {Body, Offset}
        ) ->
            NextOffset = Offset + xls_types:width(xls_types:from_erl(Type)),
            Line = io_lib:format("    ~w: raw[~w:~w],~n", [Slot, Offset, NextOffset]),
            {[Line | Body], NextOffset}
        end,
        {[], 0}, Fields
    ))),
    "  }\n",
    "}\n"].

bitsfromstruct_from_record(RecordForm) ->
    SlotFromField = fun({typed_record_field, {record_field, _1, {atom, _2, Slot}, _Default}, _Type}) -> Slot end,
    {attribute, _L, record, {NameAtom, Fields}} = RecordForm,
    Name = lists:delete($_, atom_to_list(NameAtom)),
    StructName = string:titlecase(Name),
    ["fn bits_from_", string:lowercase(StructName), "(s: ", StructName, ") -> bits[bit_count<", StructName, ">()] {\n",
    case Fields of
        [] -> "  u0:0\n";
        [{typed_record_field, {record_field, _1, {atom, _2, Slot}, _Default}, _Type}] ->
            io_lib:format("  s.~w~n", [Slot]);
        [First | Rest] ->
            ["  ", lists:foldl(
                fun(Field, Body) ->
                    Line = io_lib:format("s.~w ++ ", [SlotFromField(Field)]),
                    [Line | Body]  % implicit lists:reverse with this join order
                end,
                [io_lib:format("s.~w~n", [SlotFromField(First)])], Rest
            )]
    end,
    "}\n"].

dummy_bitsfromstruct(RecordForm) ->
    {attribute, _L, record, {NameAtom, _Fields}} = RecordForm,
    Name = lists:delete($_, atom_to_list(NameAtom)),
    StructName = string:titlecase(Name),
    ["fn bits_from_", string:lowercase(StructName), "(s: ", StructName, ") -> bits[0] { zero!<bits[0]>() }\n"].

-spec handle_cast([erl_parse:abstract_form()]) -> erl_parse:af_clause_seq().
handle_cast(Forms) ->
    find_function(Forms, handle_cast, 2).

-spec handle_call([erl_parse:abstract_form()]) -> erl_parse:af_clause_seq().
handle_call(Forms) ->
    find_function(Forms, handle_call, 2).

-spec init([erl_parse:abstract_form()]) -> erl_parse:af_clause().
init(Forms) ->
    Value = find_function(Forms, init, 1),
    1 = length(Value),
    Value.

%% TODO: be more consistent about whether you return un/packed abstract forms

-spec find_record([erl_parse:abstract_form()], atom()) -> erl_parse:af_record_decl().
find_record(Forms, Name) ->
    {value, Record} = lists:search(
        fun ({attribute, _L, record, {NameAtom, _Fields}}) -> NameAtom == Name;
            (_) -> false
        end, Forms
    ),
    Record.

-spec find_function([erl_parse:abstract_form()], atom(), integer()) -> erl_parse:af_clause_seq().
find_function(Forms, F, A) ->
    {value, {function, _LineNo, F, A, Clauses}} = lists:search(
        fun ({function, _LineNo, FF, AA, _Clauses}) ->
                F == FF andalso A == AA;
            (_) -> false
        end,
        Forms
    ),
    Clauses.

find_attribute(Forms, Atom) ->
    {value, {attribute, _L, _A, Value}} = lists:search(
        fun ({attribute, _L, A, _Value}) -> A == Atom;
            (_) -> false
        end,
        Forms
    ),
    Value.

-spec find_spec([erl_parse:abstract_form()], atom(), integer()) -> erl_parse:af_function_spec().
find_spec(Forms, F, A) ->
    {value, Spec} = lists:search(
        fun ({attribute, _LineNo, spec, {{FF, AA}, _Data}}) ->
                F == FF andalso A == AA;
            (_) -> false
        end,
        Forms
    ),
    Spec.

%%%
%%%
%%% parse transform
%%%
%%%

parse_transform(Forms, _Options) ->
    [FileAttr, ModuleAttr | TailForms] = Forms,
    {BodyForms, EOFForm} = {lists:droplast(TailForms), lists:last(TailForms)},

    PublicStructNames = find_attribute(Forms, xls_tags),
    true = length(PublicStructNames) =< ?MAX_TAGS,
    ExportAttr = {attribute, element(2, ModuleAttr), export, [{pack, 1}, {unpack, 2}, {pack_tag, 1}, {unpack_tag, 1}]},
    {eof, Line} = EOFForm,

    PackForm = {function, Line, pack, 1, [
        {clause, Line, [{match, Line, {var, Line, 'Record'}, {record, Line, Tag, []}}], [], [
            {bin, Line, [
                {bin_element, Line,
                    {record_field, Line, {var, Line, 'Record'}, Tag, {atom, Line, FieldAtom}},
                    {integer, Line, 32},  % TODO: width
                    [little, unsigned, integer]  % TODO: tags
                }
                ||  {attribute, _L, record, {_T, Fields}} <- [find_record(Forms, Tag)],
                    {typed_record_field,
                        {record_field, _1, {atom, _2, FieldAtom}, _Default},
                        {remote_type, _3, [{atom, _4, _Module}, {atom, _5, _Type}, _TypeArgs]}
                    } <- Fields
            ]}
        ]}
        ||  Tag <- PublicStructNames
    ]},

    UnpackForm = {function, Line, unpack, 2, [
        {clause, Line, [{atom, Line, Tag}, {var, Line, 'Binary'}], [], [
            {match, Line, {bin, Line, [
                {bin_element, Line,
                    {var, Line, list_to_atom(string:titlecase(atom_to_list(FieldAtom)))},
                    {integer, Line, 32},  % TODO: width
                    [little, unsigned, integer]  % TODO: descriptors
                }
                ||  {attribute, _L, record, {_T, Fields}} <- [find_record(Forms, Tag)],
                    {typed_record_field,
                        {record_field, _1, {atom, _2, FieldAtom}, _Default},
                        {remote_type, _3, [{atom, _4, _Module}, {atom, _5, _Type}, _TypeArgs]}
                    } <- Fields
                ] ++ [{bin_element, Line, {var, Line, 'Rest'}, default, [binary]}]
            }, {var, Line, 'Binary'}},
            {tuple, Line, [
                {record, Line, Tag, [
                    {record_field, Line,
                        {atom, Line, FieldAtom},
                        {var, Line, list_to_atom(string:titlecase(atom_to_list(FieldAtom)))}
                    }
                    ||  {attribute, _L, record, {_T, Fields}} <- [find_record(Forms, Tag)],
                        {typed_record_field,
                            {record_field, _1, {atom, _2, FieldAtom}, _Default},
                            _Type
                        } <- Fields
                ]},
                {var, Line, 'Rest'}
            ]}
        ]}
        ||  Tag <- PublicStructNames
    ]},

    PackTagForm = {function, Line, pack_tag, 1, [
        {clause, Line, [{atom, Line, Tag}], [], [{integer, Line, Index}]}
        ||  {Index, Tag} <- lists:enumerate([state | PublicStructNames])
    ]},

    UnpackTagForm = {function, Line, unpack_tag, 1, [
        {clause, Line, [{integer, Line, Index}], [], [{atom, Line, Tag}]}
        ||  {Index, Tag} <- lists:enumerate([state | PublicStructNames])
    ]},

    ?debug([FileAttr, ModuleAttr, ExportAttr] ++ BodyForms ++ [PackForm, UnpackForm, PackTagForm, UnpackTagForm, EOFForm]).
